"""UUIDv7 identifiers generated by the application (decision D19, RFC 9562).

Python 3.12 has no `uuid.uuid7`, so this module implements it. Within one process the
generated ids are strictly increasing: the 12-bit `rand_a` field is used as a sub-millisecond
counter (RFC 9562 section 6.2, method 1) seeded randomly at each new millisecond.
"""

from __future__ import annotations

import secrets
import threading
import time
import uuid

_COUNTER_BITS = 12
_COUNTER_MAX = (1 << _COUNTER_BITS) - 1
# Seed the counter in the lower half so a burst within one millisecond rarely overflows.
_SEED_MAX = 1 << (_COUNTER_BITS - 1)

_lock = threading.Lock()
_last_ms = -1
_counter = 0


def _next_ms_and_counter() -> tuple[int, int]:
    global _last_ms, _counter
    with _lock:
        now_ms = time.time_ns() // 1_000_000
        if now_ms > _last_ms:
            _last_ms = now_ms
            _counter = secrets.randbelow(_SEED_MAX)
        else:
            # Same millisecond, or the wall clock stepped backwards: keep ids monotonic.
            _counter += 1
            if _counter > _COUNTER_MAX:
                _last_ms += 1
                _counter = secrets.randbelow(_SEED_MAX)
        return _last_ms, _counter


def uuid7() -> uuid.UUID:
    """Return a new time-ordered UUIDv7."""
    unix_ms, counter = _next_ms_and_counter()
    rand_b = secrets.randbits(62)
    value = (unix_ms & ((1 << 48) - 1)) << 80
    value |= 0x7 << 76
    value |= counter << 64
    value |= 0b10 << 62
    value |= rand_b
    return uuid.UUID(int=value)


def uuid7_unix_ms(value: uuid.UUID) -> int:
    """Return the Unix timestamp in milliseconds embedded in a UUIDv7."""
    if value.version != 7:
        raise ValueError(f"not a UUIDv7: {value}")
    return value.int >> 80


def new_id() -> str:
    """Return a new UUIDv7 as the canonical lowercase string used on the wire."""
    return str(uuid7())
